import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int h = sc.nextInt();
        int[][] dp = new int[n + 1][n + 1];

        for (int j = 0; j <= n; j++) {
            dp[0][j] = 1;
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 0; k < i; k++) {
                    dp[i][j] += dp[k][j - 1] * dp[i - 1 - k][j - 1];
                }
            }
        }

        int result = dp[n][n] - ((h > 0) ? dp[n][h - 1] : 0);
        System.out.println(result);
        sc.close();
    }
}
